-- Compatibility: allow direct paste of VoidcoreAdvisorGenDB table where the
-- actual payload is nested under .seasonData.
if VCA.SeasonData and type(VCA.SeasonData.seasonData) == "table" then
    VCA.SeasonData = VCA.SeasonData.seasonData
end

-- Wire generated voidcache ID mappings into VCA namespace.
-- Merges SeasonData entries INTO the tables already set by Constants.lua.
-- Constants.lua wins for any key present in both — this preserves manual
-- corrections (e.g. mismatched names like Soulcoiler Nek'zali, Delver's Trove)
-- while letting the generator fill in everything it auto-matched.
if VCA.SeasonData then
    if VCA.SeasonData.dungeonVoidcacheIDs then
        VCA.DungeonVoidcacheIDs = VCA.DungeonVoidcacheIDs or {}
        for instanceID, itemID in pairs(VCA.SeasonData.dungeonVoidcacheIDs) do
            if VCA.DungeonVoidcacheIDs[instanceID] == nil then
                VCA.DungeonVoidcacheIDs[instanceID] = itemID
            end
        end
    end
    if VCA.SeasonData.raidEncounterCacheIDs then
        VCA.RaidEncounterCacheIDs = VCA.RaidEncounterCacheIDs or {}
        for encounterID, itemID in pairs(VCA.SeasonData.raidEncounterCacheIDs) do
            if VCA.RaidEncounterCacheIDs[encounterID] == nil then
                VCA.RaidEncounterCacheIDs[encounterID] = itemID
            end
        end
    end
end
